search.url:
@js:
url = "https://www.lightnovel.fun/proxy/api/search/search-result";
body = {
  is_encrypted: 0,
  platform: "pc",
  client: "web",
  sign: "",
  gz: 0,
  d: {
    q: "{{key}}",
    page: page,
    type: 0,
    security_key: JSON.parse(decodeURIComponent(cookie.getKey("https://www.lightnovel.fun/", "token"))).security_key,
  },
};
option = { method: "POST", body: JSON.stringify(body) };
option.headers = { "Content-Type": "application/json; charset=UTF-8" };
java.put("url", String(url + "," + JSON.stringify(option)));

detail.descriptionSelector:
@js:
if (result.series) {
    res = result.series.intro;
    res += "\n上传者：\n";
    result.series.editors.forEach(i => {
        res += `- 昵称：${i.nickname}|签名：${i.sign}|等级：${i.level.level}|${i.level.name}\n`;
    });
} else {
    res = result.article.summary;
}
if (result.comments) {
  res+="\n评论：\n"
  result.comments.forEach(i=>{
    res+=`- ${i.time}|${i.rate}星|${i.user_info.nickname}|${i.user_info.level.name}|${i.text}\n`
  })
}
res

chapters.listSelector:
@js:
res = []
jsContent=src.match(/<script>window.__NUXT__.+?<.script>/gi)[0].replace(/<.?script>/gi,'')
window={}
eval(jsContent)
if(window.__NUXT__.routePath.includes('detail')){
  res = [JSON.stringify(window.__NUXT__.data[0].article)]
} else {
  res = window.__NUXT__.data[0].series.articles.map(i=>JSON.stringify(i))
}
res

images.listSelector:
